// src/pages/Products.jsx

import React, { useEffect, useState } from 'react';
import { fetchBooksByCategory, fetchBooksByQuery } from '../api/books';
import { fetchCategories } from '../api/categories';
import BookCard from '../components/BookCard';
import { useAppContext } from '../context/AppContext';

function Products() {
  const [books, setBooks] = useState([]);
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('');
  const [categories, setCategories] = useState([]);
  const { addToCart, addToWishlist } = useAppContext();

  useEffect(() => {
    fetchCategories().then(setCategories);
  }, []);

  useEffect(() => {
    if (query) {
      fetchBooksByQuery(query).then(setBooks);
    } else if (category) {
      fetchBooksByCategory(category).then(setBooks);
    } else {
      fetchBooksByCategory('fiction').then(setBooks); // default
    }
  }, [query, category]);

  return (
    <div className="container">
      <h2>Browse Books</h2>

      <div className="filters">
        <input
          type="text"
          placeholder="Search by title or author"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />

        <select
          value={category}
          onChange={(e) => {
            setQuery('');
            setCategory(e.target.value);
          }}
        >
          <option value="">Select Category</option>
          {categories.map((cat) => (
            <option key={cat} value={cat}>
              {cat}
            </option>
          ))}
        </select>
      </div>

      <div className="book-grid">
        {books.map((book) => (
          <BookCard
            key={book.key}
            book={book}
            onAddToCart={addToCart}
            onAddToWishlist={addToWishlist}
          />
        ))}
      </div>
    </div>
  );
}

export default Products;
